{
  "question": "In Apple's 10-K, which specific county in California is designated for exclusive jurisdiction of disputes, and what is the minimum percentage of principal amount required to waive a past default on Notes?",
  "answer": "Santa Clara County; a majority in aggregate principal amount.",
  "quote_a": "The holders of at least a majority in aggregate principal amount of the outstanding Notes of any series may, on behalf of the holders of all Notes of that series, waive compliance",
  "quote_b": "the parties hereby submit to the exclusive jurisdiction of the State of California and agree that such litigation shall be conducted only in the courts of Santa Clara County"
}
